"""API request handling."""


class RequestValidationError(ValueError):
    """Raised when an incoming request is malformed."""


def _validate_request(data, request_id):
    """Validate the parts of a request used by the handler.

    Request bodies must be JSON-object-like dictionaries, and request IDs must
    be non-empty strings. Validation happens before any side effects (including
    audit logging).
    """
    if not isinstance(data, dict):
        raise RequestValidationError("request data must be a dictionary")

    if not isinstance(request_id, str):
        raise RequestValidationError("request_id must be a string")

    if not request_id.strip():
        raise RequestValidationError("request_id must not be empty")


def handle_request(data, request_id):
    """Validate, audit, and process an incoming API request."""
    _validate_request(data, request_id)
    audit_log(request_id, data)
    return process(data)

